// This function maps tokens to integer indexes
let tagOfToken (t:token) = 
  match t with
  | EOF  -> 0 
  | RIGHT_PAREN  -> 1 
  | LEFT_PAREN  -> 2 
  | MINUS  -> 3 
  | PLUS  -> 4 
  | SLASH  -> 5 
  | STAR  -> 6 
  | INT _ -> 7 

// This function maps integer indexes to symbolic token ids
let tokenTagToTokenId (tokenIdx:int) = 
  match tokenIdx with
  | 0 -> TOKEN_EOF 
  | 1 -> TOKEN_RIGHT_PAREN 
  | 2 -> TOKEN_LEFT_PAREN 
  | 3 -> TOKEN_MINUS 
  | 4 -> TOKEN_PLUS 
  | 5 -> TOKEN_SLASH 
  | 6 -> TOKEN_STAR 
  | 7 -> TOKEN_INT 
  | 10 -> TOKEN_end_of_input
  | 8 -> TOKEN_error
  | _ -> failwith "tokenTagToTokenId: bad token"

